"""reports/results.md, rendered from the run's numbers (never typed by hand)."""
from __future__ import annotations


def _pct(x: float, d: int = 1) -> str:
    return f"{x * 100:.{d}f} %"


def render_results(r: dict, kpi: dict) -> str:
    g, l1, l2, noop = r["generated"], r["load_2024"], r["load_2025"], r["reload_unchanged"]
    st, sc = r["cleaning_stats"], r["cleaning_vs_truth"]
    L = ["# Results", "",
         "Auto-generated by `pannes run`. **Synthetic data** reproducing the problems of real "
         "site files; no real company data is used.", "",
         f"Setup: {g['equipements']} machines (5 types x 3 sites), {g['files']} quarterly Excel "
         f"files, {g['excel_rows']:,} rows describing {g['true_breakdowns']:,} true breakdowns.",
         "", "## Incremental load", "",
         "| Run | Files loaded | Files skipped | Rows read | Rows loaded | Rows rejected |",
         "|---|---|---|---|---|---|",
         f"| 2024 files | {l1['files_loaded']} | {l1['files_skipped']} | {l1['rows_read']:,} | "
         f"{l1['rows_loaded']:,} | {l1['rows_rejected']:,} |",
         f"| same inbox again | {noop['files_loaded']} | {noop['files_skipped']} | 0 | "
         f"{noop['rows_loaded']} | 0 |",
         f"| 2025 files arrive | {l2['files_loaded']} | {l2['files_skipped']} | "
         f"{l2['rows_read']:,} | {l2['rows_loaded']:,} | {l2['rows_rejected']:,} |", "",
         f"Rejected rows overall: {st['rows_rejected']:,} of {st['rows_read']:,} "
         f"({_pct(st['rejected_share'])}). By reason: "
         + ", ".join(f"{k} {v}" for k, v in st["by_reason"].items()) + ".", "",
         "## Cleaning checked against the generator's labels", "",
         f"Clean rows wrongly rejected: {sc['clean_rows_wrongly_rejected']}; defective rows kept: "
         f"{sc['defective_rows_kept']}.", "",
         "| Injected defect | Rows | Rejected with the right reason |", "|---|---|---|"]
    for k, v in sc["per_defect"].items():
        L.append(f"| {k} | {v['injected']} | {v['caught_with_right_reason']} |")
    L += ["", "The rules were written for these defect types, so this shows they work as "
          "specified, not that they would catch unknown errors.", "",
          "## Reliability KPIs (SQL views)", "",
          f"- Breakdowns in the database: {kpi['nb_pannes']:,}",
          f"- Mean declaration delay: {kpi['delai_moyen_declaration_h']:.1f} h; declared more "
          f"than 24 h late: {_pct(kpi['part_declarations_tardives'])}",
          f"- MTTR: {kpi['mttr_h']:.1f} h; mean MTBF per machine: "
          f"{kpi['mtbf_moyen_h']:,.0f} h; mean availability: "
          f"{_pct(kpi['disponibilite_moyenne'], 2)} (lowest machine "
          f"{_pct(kpi['disponibilite_min'], 2)})", "",
          "| Part | Breakdowns | Per month | MTTR (h) |", "|---|---|---|---|"]
    for p in kpi["par_piece"][:6]:
        L.append(f"| {p['piece']} | {p['nb_pannes']} | {p['pannes_par_mois']:.1f} | "
                 f"{p['mttr_h']:.1f} |")
    L += ["", "![KPIs](kpi.png)", "",
          "These views are what a Power BI report would connect to; no Power BI report is built "
          "here.", ""]
    return "\n".join(L)
